import { createHash } from "node:crypto";
import { expect, it } from "vitest";
import { decodeImage } from "@poe-code/image-ast/portable";
import { MemoryFileSystem } from "@poe-code/safe-fs/core";
import { runConvertCli, runMogrifyCli } from "./index.js";
import fixtures from "./encipher-fixtures.json" with { type: "json" };

// Inputs are native ImageMagick ciphertext, never generated by our encipher code.
for (const retained of [false, true]) {
  for (const fixture of fixtures) {
    it(`deciphers native pixels: ${fixture.key}, ${fixture.coder}, ${fixture.size}, retained=${retained}`, async () => {
      const files = new Map([["/cipher.png", Buffer.from(fixture.cipher, "base64")], ["/key.txt", Buffer.from(fixture.key)]]);
      const fs = new MemoryFileSystem();
      for (const [path, bytes] of files) await fs.writeFile(path, bytes);
      const result = await runConvertCli(["/cipher.png", "-decipher", "/key.txt", "/recovered.png"], retained ? { filesystem: fs, cwd: "/" } : files);
      expect(result.stderr).toBe("");
      expect(result.exitCode).toBe(0);
      const actual = decodeImage(retained ? await fs.readFile("/recovered.png") : files.get("/recovered.png")!);
      const expected = decodeImage(Buffer.from(fixture.source, "base64"));
      if (fixture.coder === "PNG") {
        // This native fixture saves grayscale ciphertext as RGB, changing its
        // channel layout. Native decipher produces the same non-original pixels.
        expect(createHash("sha256").update(actual.data).digest("hex")).toBe("5e721fea2802263f504c208b998fde6e5e8776abcb74d4cf8163ec54f8a971a3");
      } else {
        expect(actual.data).toEqual(expected.data);
        expect(actual.data16).toEqual(expected.data16);
      }
      if (fixture.size === "16x12" && fixture.coder === "PNG24" && fixture.depth === 8) {
        expect(createHash("sha256").update(actual.data).digest("hex")).toBe("156e0941a82e71588f3d36a0c5ebcec3ad54a4d24f0917500682632a327e82a4");
      }
    });
  }
  it(`reports a missing key without writing output, retained=${retained}`, async () => {
    const files = new Map([["/cipher.png", Buffer.from(fixtures[0]!.cipher, "base64")]]);
    const fs = new MemoryFileSystem();
    for (const [path, bytes] of files) await fs.writeFile(path, bytes);
    const result = await runConvertCli(["/cipher.png", "-decipher", "/missing.key", "/recovered.png"], retained ? { filesystem: fs, cwd: "/" } : files);
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr).toContain("/missing.key");
    if (retained) await expect(fs.stat("/recovered.png")).rejects.toThrow();
    else expect(files.has("/recovered.png")).toBe(false);
  });
}

it("supports decipher through mogrify", async () => {
  const fixture = fixtures[0]!;
  const files = new Map([["cipher.png", Buffer.from(fixture.cipher, "base64")], ["key.txt", Buffer.from(fixture.key)]]);
  const result = await runMogrifyCli(["-decipher", "key.txt", "cipher.png"], files);
  expect(result.exitCode).toBe(0);
  expect(decodeImage(files.get("cipher.png")!).data).toEqual(decodeImage(Buffer.from(fixture.source, "base64")).data);
});
